import{_ as r,C as o,o as n,c as i,j as t,a as s,E as d,a2 as l}from"./chunks/framework.CeZVUxyP.js";const A=JSON.parse('{"title":"AI for 3D modeling and CAD","description":"","frontmatter":{},"headers":[],"relativePath":"research/ai-modeling.md","filePath":"research/ai-modeling.md","lastUpdated":1794255962000}'),c={name:"research/ai-modeling.md"};function h(p,e,m,u,f,g){const a=o("AudioSummary");return n(),i("div",null,[e[0]||(e[0]=t("h1",{id:"ai-for-3d-modeling-and-cad",tabindex:"-1"},[s("AI for 3D modeling and CAD "),t("a",{class:"header-anchor",href:"#ai-for-3d-modeling-and-cad","aria-label":'Permalink to "AI for 3D modeling and CAD"'},"​")],-1)),d(a,{id:"ai-modeling"}),e[1]||(e[1]=l('<p><strong>Source review: 2026-11-09.</strong> Candidates below have not been benchmarked by this lab. Recommendations describe our proposed tests.</p><h2 id="three-distinct-workflows" tabindex="-1">Three distinct workflows <a class="header-anchor" href="#three-distinct-workflows" aria-label="Permalink to &quot;Three distinct workflows&quot;">​</a></h2><ol><li><strong>AI writes modeling instructions:</strong> Python or CAD code creates geometry with parameters we can revise.</li><li><strong>AI generates mesh data:</strong> text or images become a mesh, followed by cleanup and integration.</li><li><strong>AI assists an established task:</strong> search, automation, deformation, or other narrowly defined operations inside a modeling application.</li></ol><p>We should evaluate these separately. Visual resemblance, a well-formed solid, and an animation-ready mesh are different outcomes.</p><h2 id="candidate-map" tabindex="-1">Candidate map <a class="header-anchor" href="#candidate-map" aria-label="Permalink to &quot;Candidate map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Documented interface or capability</th><th>Proposed use and limitation</th></tr></thead><tbody><tr><td>Blender</td><td><a href="https://docs.blender.org/api/current/" target="_blank" rel="noreferrer">Python API</a> for scene and data operations</td><td>Start here for scripted props, scene assembly, and exports. Measure whether AI scripts preserve editable structure.</td></tr><tr><td>Community MCP for Blender</td><td><a href="https://github.com/ahujasid/mcp-for-blender" target="_blank" rel="noreferrer">Project</a> connects an agent to a Blender add-on and Python server</td><td>Compare interactive tool control with direct scripts. It is a community project, not an official Blender Foundation integration.</td></tr><tr><td>AutoCAD</td><td><a href="https://help.autodesk.com/cloudhelp/2026/ENU/AutoCAD-WhatsNew/files/GUID-A656580B-871D-48A8-9559-AC71FC357E03.htm" target="_blank" rel="noreferrer">Assistant</a> provides AI-guided help; <a href="https://aps.autodesk.com/automation-apis" target="_blank" rel="noreferrer">Automation APIs</a> can run scripts and routines against DWGs</td><td>Treat product help and geometry automation as separate capabilities. Do not infer general prompt-to-model support from an assistant.</td></tr><tr><td>CadQuery</td><td><a href="https://cadquery.readthedocs.io/en/latest/" target="_blank" rel="noreferrer">Python library</a> for parametric CAD</td><td>Test precise mechanical props with dimensions and revisions. CAD output still needs a suitable mesh conversion for game use.</td></tr><tr><td>Houdini</td><td><a href="https://www.sidefx.com/docs/houdini/ml/building_blocks/framework.html" target="_blank" rel="noreferrer">ML workflow documentation</a> covers data, training, and inference stages</td><td>A later candidate for controlled procedural and learned workflows; measure setup effort before adopting it.</td></tr><tr><td>Meshy</td><td><a href="https://docs.meshy.ai/en/api/text-to-3d" target="_blank" rel="noreferrer">API</a> documents text/image generation and related remesh, UV, rigging, and animation operations</td><td>Compare rapid mesh generation with scripted assets. API availability does not establish topology quality for our use.</td></tr><tr><td>TRELLIS.2</td><td><a href="https://github.com/microsoft/TRELLIS.2" target="_blank" rel="noreferrer">Microsoft research repository</a> provides a 3D generation implementation</td><td>Research candidate; check its current hardware and dependency requirements before assuming local Mac execution.</td></tr></tbody></table><h2 id="what-the-research-literature-adds" tabindex="-1">What the research literature adds <a class="header-anchor" href="#what-the-research-literature-adds" aria-label="Permalink to &quot;What the research literature adds&quot;">​</a></h2><p><a href="https://arxiv.org/abs/2403.01248" target="_blank" rel="noreferrer">SceneCraft</a> investigates generating Blender-executable Python for scenes. <a href="https://arxiv.org/abs/2505.06507" target="_blank" rel="noreferrer">Text-to-CadQuery</a> explores translating natural language into parametric CAD code. These are useful evidence that code-based modeling is an active research direction; paper results are not a guarantee on our props or hardware.</p><h2 id="our-first-comparison" tabindex="-1">Our first comparison <a class="header-anchor" href="#our-first-comparison" aria-label="Permalink to &quot;Our first comparison&quot;">​</a></h2><p>Give all workflows a crate brief with a separate opening lid, known dimensions, a specified hinge pivot, and an engine asset budget. Compare Blender scripting with a mesh-generation route; keep the precision bracket experiment separate for CadQuery and AutoCAD.</p><p>Request a second version with a wider lid and unchanged hinge behavior. Inspect named parts, dimensions, normals, UVs, material slots, texture size, and collision. Export and run it in the actual engine. A rendered screenshot alone cannot pass the test.</p><h2 id="autocad-on-this-mac" tabindex="-1">AutoCAD on this Mac <a class="header-anchor" href="#autocad-on-this-mac" aria-label="Permalink to &quot;AutoCAD on this Mac&quot;">​</a></h2><p>Autodesk documents different programming interfaces across platforms. Confirm the specific product, edition, and version before choosing AutoLISP, .NET, or ObjectARX. Do not assume a Windows automation example will work on macOS. <a href="https://help.autodesk.com/cloudhelp/2024/ENU/AutoCAD-MAC-Customization/files/GUID-E6429154-36DF-4D84-8ABC-9FCA15B66158.htm" target="_blank" rel="noreferrer">Platform interface matrix</a> (versioned 2024 reference; recheck against the installed release).</p><p>My starting preference is Blender for game assets and CadQuery for the precision experiment. AutoCAD becomes a higher priority if our project needs DWG workflows or existing CAD content. This is a scope decision, not a claim that one application is universally better.</p>',14))])}const w=r(c,[["render",h]]);export{A as __pageData,w as default};
